-- Source: fix-booking-settings.sql
-- Existing Dojworld projects: scope the booking settings update to the hotel.
-- Preserves all settings, room mappings, policies and permissions.
create or replace function public.configure_dojworld_booking(p_enabled boolean,p_arrival_requests boolean,p_policy text) returns void
language plpgsql security definer set search_path='' as $$
declare s public.dojworld_settings%rowtype;begin
 select * into s from public.dojworld_settings where singleton=true for update;
 if not public.has_org_role(s.organization_id,array['owner']::public.member_role[]) then raise exception 'Hotel owner access required.' using errcode='42501';end if;
 if length(btrim(coalesce(p_policy,''))) not between 30 and 3000 or p_policy like 'Contact reception for cancellation or changes. Cancellation and refund terms must%' then raise exception 'Enter the actual cancellation and refund terms before enabling bookings.';end if;
 if p_enabled and exists(select 1 from public.property_tax_rules where property_id=s.property_id and active and rate_basis_points>0) then raise exception 'Use final tax-inclusive rates for online checkout. Separate tax rules are not included in web quotes.';end if;
 if p_enabled and not exists(select 1 from public.online_room_listings where enabled) then raise exception 'Verify and enable at least one room listing first.';end if;
 update public.dojworld_settings set online_enabled=p_enabled,arrival_requests_enabled=p_arrival_requests,cancellation_policy=btrim(p_policy)
 where singleton=true and organization_id=s.organization_id and property_id=s.property_id;
 insert into public.audit_events(organization_id,property_id,actor_user_id,action,entity_type,entity_id,after_data) values(s.organization_id,s.property_id,auth.uid(),'online_booking_settings_updated','property',s.property_id,jsonb_build_object('enabled',p_enabled,'policy',btrim(p_policy)));
end $$;
revoke all on function public.configure_dojworld_booking(boolean,boolean,text) from public,anon;
grant execute on function public.configure_dojworld_booking(boolean,boolean,text) to authenticated;


-- Source: bulk-online-rooms.sql
-- Existing Dojworld projects: add atomic bulk listing controls.
-- Existing paused rooms remain paused. Only newly inserted listings default on;
-- the hotel-wide online_enabled switch and live availability rules are unchanged.
alter table public.online_room_listings alter column enabled set default true;

create or replace function public.bulk_set_online_rooms(p_property_id uuid,p_slugs text[],p_enabled boolean) returns integer
language plpgsql security definer set search_path='' as $$
declare s public.dojworld_settings%rowtype;v_count integer;begin
 select * into s from public.dojworld_settings where singleton=true and property_id=p_property_id for update;
 if not found or not public.can_access_property(s.organization_id,s.property_id) or not public.has_org_role(s.organization_id,array['owner']::public.member_role[]) then
   raise exception 'Hotel owner access required.' using errcode='42501';
 end if;
 if p_enabled is null or p_slugs is null or cardinality(p_slugs) not between 1 and 1000
   or array_ndims(p_slugs)<>1 or exists(select 1 from unnest(p_slugs) slug where slug is null or length(slug) not between 1 and 100 or slug<>btrim(slug))
   or (select count(distinct slug) from unnest(p_slugs) slug)<>cardinality(p_slugs) then
   raise exception 'Choose one or more unique website room listings.' using errcode='22023';
 end if;
 perform 1 from public.online_room_listings l where l.slug=any(p_slugs) order by l.slug for update;
 select count(*) into v_count from public.online_room_listings l where l.slug=any(p_slugs);
 if v_count<>cardinality(p_slugs) then raise exception 'One or more website room listings no longer exist.' using errcode='22023';end if;
 perform 1 from public.rooms r join public.room_types t on t.id=r.room_type_id
   join public.online_room_listings l on l.room_id=r.id where l.slug=any(p_slugs) order by r.id for share of r,t;
 if exists(select 1 from public.online_room_listings l
   left join public.rooms r on r.id=l.room_id left join public.room_types t on t.id=r.room_type_id
   where l.slug=any(p_slugs) and (r.id is null or t.id is null
     or r.organization_id<>s.organization_id or r.property_id<>s.property_id
     or t.organization_id<>s.organization_id or t.property_id<>s.property_id
     or (p_enabled and (not r.active or not t.active)))) then
   raise exception 'Choose valid Dojworld room mappings. Only active rooms and room types can be enabled online.' using errcode='22023';
 end if;
 update public.online_room_listings l set enabled=p_enabled
   from public.rooms r where l.slug=any(p_slugs) and l.room_id=r.id
   and r.organization_id=s.organization_id and r.property_id=s.property_id;
 insert into public.audit_events(organization_id,property_id,actor_user_id,action,entity_type,entity_id,after_data)
   values(s.organization_id,s.property_id,auth.uid(),'online_room_listings_updated','property',s.property_id,
     jsonb_build_object('enabled',p_enabled,'slugs',to_jsonb(p_slugs),'count',v_count));
 return v_count;
end $$;
revoke all on function public.bulk_set_online_rooms(uuid,text[],boolean) from public,anon;
grant execute on function public.bulk_set_online_rooms(uuid,text[],boolean) to authenticated;

-- Source: front-desk-payments.sql
-- Atomic direct reservations and their initial payment. Safe to apply to an
-- existing dedicated installation; no guest data or historical amounts change.
create table if not exists booking_private.front_desk_requests (
  organization_id uuid not null references public.organizations,
  request_id uuid not null,
  created_by uuid not null references auth.users,
  request_payload jsonb not null,
  reservation_id uuid not null references public.reservations,
  payment_id uuid references public.payments,
  created_at timestamptz not null default now(),
  primary key (organization_id,request_id)
);
revoke all on booking_private.front_desk_requests from public,anon,authenticated;

create or replace function public.guard_verified_online_tender() returns trigger
language plpgsql set search_path='' as $$
begin
  if exists(select 1 from public.payment_methods where id=new.payment_method_id and name='Paystack online')
    and coalesce(auth.role(),'')<>'service_role' then
    raise exception 'Online payments are recorded only after Paystack verification. Choose the method actually received at reception.' using errcode='42501';
  end if;
  return new;
end $$;
revoke all on function public.guard_verified_online_tender() from public,anon,authenticated;
drop trigger if exists payment_verified_online_tender on public.payments;
create trigger payment_verified_online_tender before insert on public.payments
  for each row execute function public.guard_verified_online_tender();

create or replace function public.create_front_desk_reservation(
  p_request_id uuid,p_organization_id uuid,p_property_id uuid,p_room_id uuid,
  p_guest_name text,p_guest_phone text,p_guest_email text,p_arrival_date date,p_departure_date date,
  p_adults smallint,p_nightly_rate_kobo bigint,p_notes text,p_pricing_reason text,p_expected_quote jsonb,
  p_payment_state text,p_payment_method_id uuid,p_amount_kobo bigint,p_reference text
) returns jsonb language plpgsql security definer set search_path='' as $$
declare
  v_payload jsonb;v_existing booking_private.front_desk_requests%rowtype;
  v_reservation uuid;v_payment uuid;v_total bigint;
begin
  if auth.uid() is null or not public.has_org_role(p_organization_id,array['owner','manager','front_desk']::public.member_role[])
    or not public.can_access_property(p_organization_id,p_property_id) then
    raise exception 'You cannot create reservations for this property.' using errcode='42501';
  end if;
  if p_request_id is null or p_payment_state is null or p_payment_state not in ('unpaid','received') then
    raise exception 'Choose unpaid or payment received before confirming.' using errcode='22023';
  end if;
  if p_payment_state='unpaid' and (p_payment_method_id is not null or coalesce(p_amount_kobo,0)<>0 or nullif(btrim(p_reference),'') is not null) then
    raise exception 'Unpaid reservations cannot include a payment.' using errcode='22023';
  end if;
  if p_payment_state='received' and (p_payment_method_id is null or coalesce(p_amount_kobo,0)<=0 or p_amount_kobo>9007199254740991) then
    raise exception 'Enter the amount received and its payment method.' using errcode='22023';
  end if;
  if p_expected_quote is null or jsonb_typeof(p_expected_quote)<>'array' or jsonb_array_length(p_expected_quote)=0 then
    raise exception 'Load and review the nightly quote before confirming.' using errcode='22023';
  end if;
  if length(coalesce(p_reference,''))>150 then raise exception 'Payment reference must be 150 characters or fewer.' using errcode='22023';end if;
  v_payload:=jsonb_build_object('property',p_property_id,'room',p_room_id,'name',p_guest_name,'phone',p_guest_phone,
    'email',p_guest_email,'arrival',p_arrival_date,'departure',p_departure_date,'adults',p_adults,
    'rate',p_nightly_rate_kobo,'notes',p_notes,'reason',p_pricing_reason,'quote',p_expected_quote,
    'paymentState',p_payment_state,'method',p_payment_method_id,'amount',p_amount_kobo,'reference',p_reference);
  perform pg_advisory_xact_lock(hashtextextended('front-desk:'||p_organization_id::text||':'||p_request_id::text,0));
  select * into v_existing from booking_private.front_desk_requests
    where organization_id=p_organization_id and request_id=p_request_id;
  if found then
    if v_existing.created_by<>auth.uid() or v_existing.request_payload<>v_payload then
      raise exception 'This reservation was already saved with different details. Open a new reservation to make another booking.' using errcode='23505';
    end if;
    return jsonb_build_object('reservationId',v_existing.reservation_id,'paymentId',v_existing.payment_id);
  end if;
  v_reservation:=public.create_priced_reservation(p_organization_id,p_property_id,p_room_id,p_guest_name,p_guest_phone,
    p_guest_email,p_arrival_date,p_departure_date,p_adults,p_nightly_rate_kobo,p_notes,p_pricing_reason,p_expected_quote);
  select sum(charged_rate_kobo) into v_total from public.reservation_night_rates where reservation_id=v_reservation;
  if p_payment_state='received' then
    if p_amount_kobo>coalesce(v_total,0) then
      raise exception 'The initial payment cannot exceed the agreed room total.' using errcode='22023';
    end if;
    if not exists(select 1 from public.payment_methods where id=p_payment_method_id and organization_id=p_organization_id
      and property_id=p_property_id and active and name<>'Paystack online') then
      raise exception 'Choose an active reception payment method.' using errcode='22023';
    end if;
    v_payment:=public.record_reservation_deposit(v_reservation,p_payment_method_id,p_amount_kobo,p_reference,'front-desk:'||p_request_id::text);
  end if;
  insert into booking_private.front_desk_requests(organization_id,request_id,created_by,request_payload,reservation_id,payment_id)
    values(p_organization_id,p_request_id,auth.uid(),v_payload,v_reservation,v_payment);
  return jsonb_build_object('reservationId',v_reservation,'paymentId',v_payment);
end $$;
revoke all on function public.create_front_desk_reservation(uuid,uuid,uuid,uuid,text,text,text,date,date,smallint,bigint,text,text,jsonb,text,uuid,bigint,text) from public,anon;
grant execute on function public.create_front_desk_reservation(uuid,uuid,uuid,uuid,text,text,text,date,date,smallint,bigint,text,text,jsonb,text,uuid,bigint,text) to authenticated;

-- Source: reservation-payment-summary.sql
-- Additive update for existing Dojworld projects. No settings or inventory change.
-- Payment totals include the complete ledger history, independent of UI row limits.

create or replace function public.get_reservation_payment_summaries(
  p_property_id uuid,
  p_reservation_ids uuid[]
) returns table (
  reservation_id uuid,
  room_total_kobo bigint,
  gross_paid_kobo bigint,
  refunded_kobo bigint,
  net_paid_kobo bigint,
  payment_methods text[],
  latest_payment_id uuid
) language plpgsql stable security definer set search_path='' as $$
declare v_organization_id uuid;
begin
  select p.organization_id into v_organization_id
    from public.properties p where p.id=p_property_id;
  if v_organization_id is null
    or not public.can_access_property(v_organization_id,p_property_id)
    or not public.has_org_role(v_organization_id,array['owner','manager','front_desk','accountant']::public.member_role[])
  then
    raise exception 'Payment access to this hotel is required.' using errcode='42501';
  end if;
  if p_reservation_ids is null or array_position(p_reservation_ids,null) is not null then
    raise exception 'Choose valid reservation IDs.' using errcode='22023';
  end if;
  -- Never silently omit another property's or an unknown reservation.
  if exists (
    select 1 from unnest(p_reservation_ids) requested(id)
    left join public.reservations r on r.id=requested.id
      and r.organization_id=v_organization_id and r.property_id=p_property_id
    where r.id is null
  ) then
    raise exception 'Choose only reservations from this hotel.' using errcode='42501';
  end if;
  -- A missing quote must not be reported as a complimentary or fully paid stay.
  if exists (
    select 1 from public.reservations r
    where r.id=any(p_reservation_ids)
      and exists(select 1 from public.reservation_rooms rr where rr.reservation_id=r.id)
      and (select count(*) from public.reservation_night_rates n
        where n.reservation_id=r.id and n.organization_id=v_organization_id
          and n.property_id=p_property_id and n.service_date>=r.arrival_date
          and n.service_date<r.departure_date)<>r.departure_date-r.arrival_date
  ) then
    raise exception 'Some agreed nightly prices are missing. Ask the hotel administrator to review the stay.' using errcode='23514';
  end if;

  return query
  with requested as (
    select r.id,r.arrival_date,r.departure_date from public.reservations r
    where r.organization_id=v_organization_id and r.property_id=p_property_id
      and r.id=any(p_reservation_ids)
  ), quotes as (
    select r.id,sum(n.charged_rate_kobo)::bigint total
    from requested r join public.reservation_night_rates n
      on n.reservation_id=r.id and n.organization_id=v_organization_id
      and n.property_id=p_property_id and n.service_date>=r.arrival_date
      and n.service_date<r.departure_date
    group by r.id
  ), receipts as (
    select f.reservation_id,p.id,p.amount_kobo,p.received_at,m.name,
      coalesce((select sum(rf.amount_kobo) from public.payment_refunds rf
        where rf.payment_id=p.id and rf.organization_id=v_organization_id
          and rf.property_id=p_property_id),0)::bigint refunded
    from requested r join public.folios f on f.reservation_id=r.id
      and f.organization_id=v_organization_id and f.property_id=p_property_id
    join public.payments p on p.folio_id=f.id
      and p.organization_id=v_organization_id and p.property_id=p_property_id
    join public.payment_methods m on m.id=p.payment_method_id
      and m.organization_id=v_organization_id and m.property_id=p_property_id
  ), totals as (
    select rc.reservation_id,sum(rc.amount_kobo)::bigint gross,
      sum(rc.refunded)::bigint refunded,
      array_agg(distinct rc.name order by rc.name) methods,
      (array_agg(rc.id order by rc.received_at desc,rc.id desc))[1] latest
    from receipts rc group by rc.reservation_id
  )
  select r.id,coalesce(q.total,0)::bigint,coalesce(t.gross,0)::bigint,
    coalesce(t.refunded,0)::bigint,
    (coalesce(t.gross,0)-coalesce(t.refunded,0))::bigint,
    coalesce(t.methods,array[]::text[]),t.latest
  from requested r left join quotes q on q.id=r.id
    left join totals t on t.reservation_id=r.id
  order by r.id;
end $$;

revoke all on function public.get_reservation_payment_summaries(uuid,uuid[]) from public,anon,authenticated;
grant execute on function public.get_reservation_payment_summaries(uuid,uuid[]) to authenticated;
comment on function public.get_reservation_payment_summaries(uuid,uuid[]) is
  'Read-only staff totals: immutable quoted room prices and all actual receipts less recorded refunds. Full prepayments remain accounting advances; payment status must use net amounts.';

notify pgrst,'reload schema';

-- Source: channel-reservations.sql
-- Booking sources share the hotel's existing reservations and room locks.
-- Booking.com automation is not enabled by this update. Tasks are manual checks.
alter table public.reservations
 add column if not exists external_reference text check(length(external_reference)<=100),
 add column if not exists external_unit_reference text check(length(external_unit_reference)<=100),
 add column if not exists channel_name text check(length(channel_name)<=80),
 add column if not exists guaranteed_unpaid boolean not null default true,
 add column if not exists payment_deadline timestamptz,
 add column if not exists channel_collection text not null default 'unknown'
   check(channel_collection in ('unknown','pay_at_hotel','collected_by_channel'));
create unique index if not exists reservation_booking_com_reference
 on public.reservations(property_id,lower(btrim(external_reference)),lower(coalesce(nullif(btrim(external_unit_reference),''),'1')))
 where source='booking_com' and nullif(btrim(external_reference),'') is not null;

create table if not exists booking_private.channel_requests (
 organization_id uuid not null references public.organizations,
 request_id uuid not null,
 channel_payload jsonb not null,
 reservation_id uuid not null references public.reservations,
 primary key(organization_id,request_id)
);
revoke all on booking_private.channel_requests from public,anon,authenticated;

drop function if exists public.create_channel_reservation(uuid,uuid,uuid,uuid,text,text,text,date,date,smallint,bigint,text,text,jsonb,text,uuid,bigint,text,text,text,text,text,text);
create or replace function public.create_channel_reservation(
 p_request_id uuid,p_organization_id uuid,p_property_id uuid,p_room_id uuid,
 p_guest_name text,p_guest_phone text,p_guest_email text,p_arrival_date date,p_departure_date date,
 p_adults smallint,p_nightly_rate_kobo bigint,p_notes text,p_pricing_reason text,p_expected_quote jsonb,
 p_payment_state text,p_payment_method_id uuid,p_amount_kobo bigint,p_reference text,
 p_source text,p_external_reference text,p_external_unit_reference text,p_channel_name text,p_channel_collection text,
 p_guaranteed_unpaid boolean,p_payment_deadline timestamptz
) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_metadata jsonb;v_previous booking_private.channel_requests%rowtype;v_result jsonb;
 v_external text:=nullif(btrim(p_external_reference),'');v_unit text:=nullif(btrim(p_external_unit_reference),'');
 v_name text:=nullif(btrim(p_channel_name),'');v_reservation uuid;
begin
 if auth.uid() is null or not public.can_access_property(p_organization_id,p_property_id)
  or not public.has_org_role(p_organization_id,array['owner','manager','front_desk']::public.member_role[]) then
  raise exception 'You cannot create reservations for this property.' using errcode='42501';end if;
 if p_request_id is null or p_source is null or p_source not in ('direct','phone','whatsapp','booking_com','other')
  or coalesce(length(v_external),0)>100 or coalesce(length(v_unit),0)>100 or coalesce(length(v_name),0)>80
  or (p_source='booking_com' and v_external is null) or (p_source='other' and coalesce(length(v_name),0)<2)
  or p_channel_collection is null or p_channel_collection not in ('unknown','pay_at_hotel','collected_by_channel')
  or (p_source not in ('booking_com','other') and p_channel_collection<>'unknown') then
  raise exception 'Choose a booking source and valid channel reference and collection details.' using errcode='22023';end if;
 if p_guaranteed_unpaid is null or (p_source in ('booking_com','other') and not p_guaranteed_unpaid) or (p_guaranteed_unpaid and p_payment_deadline is not null)
  or (not p_guaranteed_unpaid and (p_payment_state<>'unpaid' or p_payment_deadline is null
  or p_payment_deadline>(p_arrival_date+time '23:59') at time zone 'Africa/Lagos')) then
  raise exception 'Choose a guaranteed reservation or an unpaid hold with a future deadline no later than arrival day.' using errcode='22023';end if;
 if p_source<>'other' then v_name:=null;end if;
 if p_source='booking_com' then v_unit:=coalesce(v_unit,'1');end if;
 v_metadata:=jsonb_build_object('source',p_source,'reference',v_external,'unit',v_unit,'name',v_name,'collection',p_channel_collection,'guaranteed',p_guaranteed_unpaid,'deadline',p_payment_deadline);
 -- Use the same request lock as the atomic reservation/payment transaction.
 perform pg_advisory_xact_lock(hashtextextended('front-desk:'||p_organization_id::text||':'||p_request_id::text,0));
 select * into v_previous from booking_private.channel_requests where organization_id=p_organization_id and request_id=p_request_id;
 if found then
  if v_previous.channel_payload<>v_metadata then raise exception 'This booking attempt already used different channel details. Open a new reservation.' using errcode='23505';end if;
 elsif exists(select 1 from booking_private.front_desk_requests where organization_id=p_organization_id and request_id=p_request_id) then
  raise exception 'This booking attempt was already used. Open a new reservation.' using errcode='23505';
 end if;
 if v_previous.reservation_id is null and not p_guaranteed_unpaid and p_payment_deadline<=now() then
  raise exception 'Choose a future unpaid hold deadline.' using errcode='22023';end if;
 if p_source='booking_com' then
  perform pg_advisory_xact_lock(hashtextextended('booking-com:'||p_property_id::text||':'||lower(v_external)||':'||lower(v_unit),0));
  if exists(select 1 from public.reservations r where r.property_id=p_property_id and r.source='booking_com'
   and lower(btrim(r.external_reference))=lower(v_external)
   and lower(coalesce(nullif(btrim(r.external_unit_reference),''),'1'))=lower(v_unit)
   and r.id is distinct from v_previous.reservation_id) then
   raise exception 'This Booking.com reservation and room item are already recorded. Open the existing booking to make changes.' using errcode='23505';
  end if;
 end if;
 -- Existing pricing approvals, physical-room locks, receipts and retry checks apply.
 v_result:=public.create_front_desk_reservation(p_request_id,p_organization_id,p_property_id,p_room_id,p_guest_name,p_guest_phone,p_guest_email,
  p_arrival_date,p_departure_date,p_adults,p_nightly_rate_kobo,p_notes,p_pricing_reason,p_expected_quote,
  p_payment_state,p_payment_method_id,p_amount_kobo,p_reference);
 v_reservation:=(v_result->>'reservationId')::uuid;
 if v_previous.reservation_id is null then
  update public.reservations set source=p_source,external_reference=v_external,external_unit_reference=v_unit,
   channel_name=v_name,channel_collection=p_channel_collection,guaranteed_unpaid=p_guaranteed_unpaid,payment_deadline=p_payment_deadline
   where id=v_reservation and organization_id=p_organization_id and property_id=p_property_id;
  insert into booking_private.channel_requests(organization_id,request_id,channel_payload,reservation_id)
   values(p_organization_id,p_request_id,v_metadata,v_reservation);
  insert into public.audit_events(organization_id,property_id,actor_user_id,action,entity_type,entity_id,after_data)
   values(p_organization_id,p_property_id,auth.uid(),'reservation_channel_recorded','reservation',v_reservation,v_metadata);
 end if;
 return v_result;
end $$;
revoke all on function public.create_channel_reservation(uuid,uuid,uuid,uuid,text,text,text,date,date,smallint,bigint,text,text,jsonb,text,uuid,bigint,text,text,text,text,text,text,boolean,timestamptz) from public,anon;
grant execute on function public.create_channel_reservation(uuid,uuid,uuid,uuid,text,text,text,date,date,smallint,bigint,text,text,jsonb,text,uuid,bigint,text,text,text,text,text,text,boolean,timestamptz) to authenticated;

create table if not exists public.channel_inventory_tasks (
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null references public.organizations,
 property_id uuid not null references public.properties,
 reservation_id uuid not null references public.reservations,
 reason text not null,
 status text not null default 'pending' check(status in ('pending','completed')),
 created_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp(),
 completed_at timestamptz,
 completed_by uuid references auth.users,
 completion_note text
);
