create trigger reservation_room_channel_inventory_changed after insert or update of room_id,check_in_date,check_out_date or delete on public.reservation_rooms
 for each row execute function booking_private.channel_room_changed();

create or replace function public.complete_channel_inventory_task(p_id uuid,p_expected_updated_at timestamptz,p_note text) returns void
language plpgsql security definer set search_path='' as $$
declare t public.channel_inventory_tasks%rowtype;
begin
 select * into t from public.channel_inventory_tasks where id=p_id for update;
 if not found or not public.can_access_property(t.organization_id,t.property_id)
  or not public.has_org_role(t.organization_id,array['owner','manager','front_desk']::public.member_role[]) then
  raise exception 'Reception access required.' using errcode='42501';end if;
 if t.status='completed' then return;end if;
 if p_expected_updated_at is distinct from t.updated_at then raise exception 'This reservation changed. Refresh and check Booking.com again before completing this task.' using errcode='23514';end if;
 if length(btrim(coalesce(p_note,''))) not between 5 and 500 then raise exception 'Record what you checked or updated in Booking.com.' using errcode='22023';end if;
 update public.channel_inventory_tasks set status='completed',completed_at=clock_timestamp(),completed_by=auth.uid(),completion_note=btrim(p_note)
  where id=t.id and status='pending';
 insert into public.audit_events(organization_id,property_id,actor_user_id,action,entity_type,entity_id,after_data)
  values(t.organization_id,t.property_id,auth.uid(),'channel_inventory_manually_checked','reservation',t.reservation_id,jsonb_build_object('task',t.id,'note',btrim(p_note)));
end $$;
revoke all on function public.complete_channel_inventory_task(uuid,timestamptz,text) from public,anon;
grant execute on function public.complete_channel_inventory_task(uuid,timestamptz,text) to authenticated;

-- Existing active stays also need a calendar check. Replaying preserves completions.
insert into public.channel_inventory_tasks(organization_id,property_id,reservation_id,reason)
 select r.organization_id,r.property_id,r.id,'Existing reservation: check Booking.com calendar'
 from public.reservations r join public.dojworld_settings s on s.property_id=r.property_id and s.singleton=true
 where r.status in ('inquiry','confirmed','checked_in') and not exists(select 1 from public.channel_inventory_tasks t where t.reservation_id=r.id)
 on conflict(reservation_id) where status='pending' do nothing;
notify pgrst,'reload schema';

-- Source: booking-notifications.sql
-- Server-only recovery links and a durable transactional email outbox.
create table if not exists booking_private.guest_booking_sessions(
 token_hash text primary key,booking_id uuid not null references public.online_bookings,expires_at timestamptz not null
);
create table if not exists booking_private.booking_recovery_links(
 token_hash text primary key,booking_id uuid not null references public.online_bookings,expires_at timestamptz not null,used_at timestamptz
);
revoke all on booking_private.guest_booking_sessions,booking_private.booking_recovery_links from public,anon,authenticated;
create or replace function booking_private.has_booking_access(p_id uuid,p_token text) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.online_bookings b where b.id=p_id and (b.access_hash=encode(public.digest(p_token,'sha256'),'hex')
  or exists(select 1 from booking_private.guest_booking_sessions s where s.booking_id=b.id and s.token_hash=encode(public.digest(p_token,'sha256'),'hex') and s.expires_at>now())))
$$;
revoke all on function booking_private.has_booking_access(uuid,text) from public,anon,authenticated;

create or replace function public.prepare_booking_recovery(p_reference text,p_email text,p_token_hash text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare b public.online_bookings%rowtype;
begin
 if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid recovery token.' using errcode='22023';end if;
 select * into b from public.online_bookings where payment_reference=upper(btrim(p_reference)) and guest_email=lower(btrim(p_email));
 -- Payment reference has a mixed-case prefix followed by lower-case UUID hex.
 if not found then select * into b from public.online_bookings where lower(payment_reference)=lower(btrim(p_reference)) and guest_email=lower(btrim(p_email));end if;
 if not found then return null;end if;
 insert into booking_private.booking_recovery_links(token_hash,booking_id,expires_at) values(p_token_hash,b.id,now()+interval '20 minutes');
 return jsonb_build_object('id',b.id,'email',b.guest_email);
end $$;
create or replace function public.consume_booking_recovery(p_token_hash text,p_session_hash text) returns uuid
language plpgsql security definer set search_path='' as $$
declare l booking_private.booking_recovery_links%rowtype;
begin
 if p_session_hash is null or p_session_hash !~ '^[a-f0-9]{64}$' then raise exception 'Invalid session token.' using errcode='22023';end if;
 select * into l from booking_private.booking_recovery_links where token_hash=p_token_hash and used_at is null and expires_at>now() for update;
 if not found then raise exception 'This recovery link has expired or was already used. Request another link.' using errcode='P0002';end if;
 update booking_private.booking_recovery_links set used_at=now() where token_hash=l.token_hash and used_at is null;
 insert into booking_private.guest_booking_sessions(token_hash,booking_id,expires_at) values(p_session_hash,l.booking_id,now()+interval '30 days');
 return l.booking_id;
end $$;
revoke all on function public.prepare_booking_recovery(text,text,text),public.consume_booking_recovery(text,text) from public,anon,authenticated;
grant execute on function public.prepare_booking_recovery(text,text,text),public.consume_booking_recovery(text,text) to service_role;

create table if not exists public.booking_notifications(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations,property_id uuid not null references public.properties,
 booking_id uuid not null references public.online_bookings,transaction_id bigint not null,
 kind text not null,recipient text not null,payload jsonb not null,
 status text not null default 'pending' check(status in ('pending','processing','sent','failed')),
 attempts integer not null default 0,lease_id uuid,lease_until timestamptz,last_error text,provider_id text,
 created_at timestamptz not null default clock_timestamp(),sent_at timestamptz,
 unique(booking_id,transaction_id)
);
alter table public.booking_notifications enable row level security;
revoke all on public.booking_notifications from public,anon,authenticated;
grant select on public.booking_notifications to authenticated;
drop policy if exists booking_notification_staff_read on public.booking_notifications;
create policy booking_notification_staff_read on public.booking_notifications for select to authenticated
 using(public.can_access_property(organization_id,property_id) and public.has_org_role(organization_id,array['owner','manager','front_desk']::public.member_role[]));

create or replace function booking_private.enqueue_booking_notification(p_booking_id uuid,p_kind text) returns void
language plpgsql security definer set search_path='' as $$
declare b public.online_bookings%rowtype;r public.reservations%rowtype;v_room text;v_payload jsonb;
begin
 select * into b from public.online_bookings where id=p_booking_id;
 if not found or (p_kind='stay_updated' and b.state<>'confirmed') then return;end if;
 select * into r from public.reservations where id=b.reservation_id;
 select rm.room_number into v_room from public.reservation_rooms rr join public.rooms rm on rm.id=rr.room_id where rr.reservation_id=b.reservation_id order by rr.id limit 1;
 v_payload:=jsonb_build_object('reference',b.payment_reference,'state',b.state,'room',coalesce(v_room,b.slug),
  'arrival',coalesce(r.arrival_date,b.arrival_date),'departure',coalesce(r.departure_date,b.departure_date),'reservationStatus',r.status);
 insert into public.booking_notifications(organization_id,property_id,booking_id,transaction_id,kind,recipient,payload)
 values(b.organization_id,b.property_id,b.id,txid_current(),p_kind,b.guest_email,v_payload)
 on conflict(booking_id,transaction_id) do update set kind=excluded.kind,payload=excluded.payload,recipient=excluded.recipient;
end $$;
revoke all on function booking_private.enqueue_booking_notification(uuid,text) from public,anon,authenticated;
create or replace function booking_private.online_state_notification() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 if tg_op='INSERT' then
  if new.state='requested' then perform booking_private.enqueue_booking_notification(new.id,'requested');end if;
 elsif new.state is distinct from old.state and new.state in ('confirmed','expired','rejected','cancelled','payment_review') then
  perform booking_private.enqueue_booking_notification(new.id,new.state);
 end if;
 return new;
end $$;
drop trigger if exists online_booking_state_notification on public.online_bookings;
create trigger online_booking_state_notification after insert or update of state on public.online_bookings for each row execute function booking_private.online_state_notification();
create or replace function booking_private.stay_change_notification() returns trigger
language plpgsql security definer set search_path='' as $$
declare v_res uuid;v_booking uuid;
begin
 if tg_table_name='reservations' then
  if (new.status,new.arrival_date,new.departure_date,new.adults) is not distinct from (old.status,old.arrival_date,old.departure_date,old.adults) then return new;end if;
  v_res:=new.id;
 else
  if (new.room_id,new.check_in_date,new.check_out_date) is not distinct from (old.room_id,old.check_in_date,old.check_out_date) then return new;end if;
  v_res:=new.reservation_id;
 end if;
 select id into v_booking from public.online_bookings where reservation_id=v_res;
 if found then perform booking_private.enqueue_booking_notification(v_booking,'stay_updated');end if;
 return new;
end $$;
drop trigger if exists zz_stay_change_notification on public.reservations;
create trigger zz_stay_change_notification after update of status,arrival_date,departure_date,adults on public.reservations for each row execute function booking_private.stay_change_notification();
drop trigger if exists zz_room_change_notification on public.reservation_rooms;
create trigger zz_room_change_notification after update of room_id,check_in_date,check_out_date on public.reservation_rooms for each row execute function booking_private.stay_change_notification();
revoke all on function booking_private.online_state_notification(),booking_private.stay_change_notification() from public,anon,authenticated;

create or replace function public.claim_booking_notifications(p_limit integer) returns setof public.booking_notifications
language plpgsql security definer set search_path='' as $$
begin
 return query with jobs as (select id from public.booking_notifications where attempts<5 and (status in ('pending','failed') or (status='processing' and lease_until<now()))
  order by created_at for update skip locked limit least(greatest(p_limit,1),25))
 update public.booking_notifications n set status='processing',attempts=n.attempts+1,lease_id=gen_random_uuid(),lease_until=now()+interval '5 minutes',last_error=null
 from jobs where n.id=jobs.id returning n.*;
end $$;
create or replace function public.finish_booking_notification(p_id uuid,p_lease uuid,p_success boolean,p_provider text,p_error text) returns void
language plpgsql security definer set search_path='' as $$
begin
 update public.booking_notifications set status=case when p_success then 'sent' else 'failed' end,sent_at=case when p_success then now() end,
  provider_id=left(p_provider,150),last_error=left(p_error,200),lease_until=null
 where id=p_id and lease_id=p_lease and status='processing';
 if not found then raise exception 'Notification lease expired.' using errcode='23514';end if;
end $$;
revoke all on function public.claim_booking_notifications(integer),public.finish_booking_notification(uuid,uuid,boolean,text,text) from public,anon,authenticated;
grant execute on function public.claim_booking_notifications(integer),public.finish_booking_notification(uuid,uuid,boolean,text,text) to service_role;
create or replace function public.retry_booking_notification(p_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare n public.booking_notifications%rowtype;
begin
 select * into n from public.booking_notifications where id=p_id for update;
 if not found or not(public.can_access_property(n.organization_id,n.property_id) and public.has_org_role(n.organization_id,array['owner','manager','front_desk']::public.member_role[])) then raise exception 'Hotel access required.' using errcode='42501';end if;
 if n.status<>'failed' and not(n.status='processing' and n.lease_until<now()) then raise exception 'Only failed or stalled messages can be retried.' using errcode='23514';end if;
 update public.booking_notifications set status='pending',attempts=0,lease_id=null,lease_until=null,last_error=null where id=n.id;
 insert into public.audit_events(organization_id,property_id,actor_user_id,action,entity_type,entity_id)
 values(n.organization_id,n.property_id,auth.uid(),'booking_email_retry','booking_notification',n.id);
end $$;
revoke all on function public.retry_booking_notification(uuid) from public,anon;
grant execute on function public.retry_booking_notification(uuid) to authenticated;
notify pgrst,'reload schema';

-- Source: booking-lifecycle.sql
-- Preserve original booking/payment snapshots while showing current stays.
create or replace function booking_private.expire_direct_room(p_room uuid) returns void
language plpgsql security definer set search_path='' as $$
declare r record;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_room::text,0));
 for r in select b.id,b.organization_id,b.property_id from public.reservations b
  where b.status='confirmed' and not b.guaranteed_unpaid and b.payment_deadline<=now()
  and exists(select 1 from public.reservation_rooms rr where rr.reservation_id=b.id and rr.room_id=p_room)
  order by b.id for update loop
  if exists(select 1 from public.payments p join public.folios f on f.id=p.folio_id where f.reservation_id=r.id) then
   update public.reservations set guaranteed_unpaid=true,payment_deadline=null where id=r.id;
  else
   update public.reservations set status='cancelled',payment_deadline=null where id=r.id and status='confirmed';
   insert into public.audit_events(organization_id,property_id,action,entity_type,entity_id,after_data)
    values(r.organization_id,r.property_id,'unpaid_hold_expired','reservation',r.id,jsonb_build_object('reason','The temporary unpaid hold deadline passed.'));
  end if;
 end loop;
end $$;
revoke all on function booking_private.expire_direct_room(uuid) from public,anon,authenticated;
create or replace function booking_private.protect_paid_hold() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 update public.reservations r set guaranteed_unpaid=true,payment_deadline=null from public.folios f
 where f.id=new.folio_id and r.id=f.reservation_id and not r.guaranteed_unpaid;
 return new;
end $$;
revoke all on function booking_private.protect_paid_hold() from public,anon,authenticated;
drop trigger if exists protect_paid_reservation_hold on public.payments;
create trigger protect_paid_reservation_hold after insert on public.payments for each row execute function booking_private.protect_paid_hold();

create or replace function booking_private.expire_room(p_room uuid) returns void
language plpgsql security definer set search_path='' as $$
declare b public.online_bookings%rowtype;paid bigint;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_room::text,0));
 for b in select * from public.online_bookings where room_id=p_room and state in ('payment_pending','confirmed') and expires_at<=now() order by id for update loop
  select coalesce(sum(p.amount_kobo),0) into paid from public.payments p join public.folios f on f.id=p.folio_id where f.reservation_id=b.reservation_id;
  if paid>0 or exists(select 1 from public.reservations r where r.id=b.reservation_id and r.status<>'inquiry' and (b.payment_plan<>'arrival' or r.status<>'confirmed')) then
   update public.online_bookings set expires_at=null where id=b.id;continue;
  end if;
  update public.reservations set status='cancelled' where id=b.reservation_id and status in ('inquiry','confirmed');
  update public.online_bookings set state='expired',decision_note='The unpaid reservation deadline has passed.' where id=b.id;
 end loop;
 perform booking_private.expire_direct_room(p_room);
end $$;

create or replace function public.release_expired_online_bookings(p_property_id uuid) returns void
language plpgsql security definer set search_path='' as $$
declare r record;o uuid;
begin
 select organization_id into o from public.dojworld_settings where property_id=p_property_id;
 if o is null or (coalesce(auth.role(),'')<>'service_role' and not(public.can_access_property(o,p_property_id) and public.has_org_role(o,array['owner','manager','front_desk']::public.member_role[]))) then raise exception 'Hotel access required.' using errcode='42501';end if;
 for r in select room_id from public.online_bookings where property_id=p_property_id and state in ('payment_pending','confirmed') and expires_at<=now()
  union select rr.room_id from public.reservations b join public.reservation_rooms rr on rr.reservation_id=b.id
   where b.property_id=p_property_id and b.status='confirmed' and not b.guaranteed_unpaid and b.payment_deadline<=now()
  order by room_id loop perform booking_private.expire_room(r.room_id);end loop;
end $$;

create or replace function public.get_available_rooms(p_property_id uuid,p_arrival date,p_departure date)
returns table(room_id uuid,room_number text,room_type text,nightly_rate_kobo bigint,housekeeping_status public.room_housekeeping_status)
language plpgsql security definer set search_path='' as $$
declare v_org uuid;v_room record;
begin
 select organization_id into v_org from public.properties where id=p_property_id;
 if not found or not public.can_access_property(v_org,p_property_id) then raise exception 'You cannot view this property.' using errcode='42501';end if;
 if p_arrival is null or p_departure is null or p_departure<=p_arrival or p_departure-p_arrival>366 then raise exception 'Choose valid dates up to one year apart.' using errcode='22023';end if;
 for v_room in select rr.room_id from public.reservations b join public.reservation_rooms rr on rr.reservation_id=b.id
  where b.property_id=p_property_id and b.status='confirmed' and not b.guaranteed_unpaid and b.payment_deadline<=now()
  union select b.room_id from public.online_bookings b where b.property_id=p_property_id and b.state in ('payment_pending','confirmed') and b.expires_at<=now()
  order by room_id loop perform booking_private.expire_room(v_room.room_id);end loop;
 return query select r.id,r.room_number,rt.name,rt.base_rate_kobo,r.housekeeping_status from public.rooms r
  join public.room_types rt on rt.organization_id=r.organization_id and rt.id=r.room_type_id and rt.property_id=r.property_id
  where r.organization_id=v_org and r.property_id=p_property_id and r.active and rt.active and r.housekeeping_status<>'out_of_order'
  and not exists(select 1 from public.maintenance_work_orders m where m.room_id=r.id and m.blocks_inventory and m.status in ('open','in_progress'))
  and not exists(select 1 from public.reservation_rooms rr join public.reservations rs on rs.organization_id=rr.organization_id and rs.id=rr.reservation_id
   where rr.organization_id=v_org and rr.room_id=r.id and rs.status in ('inquiry','confirmed','checked_in') and rr.check_in_date<p_departure and rr.check_out_date>p_arrival)
  order by r.room_number;
end $$;

create or replace function public.online_booking_status(p_id uuid,p_token text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare b public.online_bookings%rowtype;r public.reservations%rowtype;paid bigint;total bigint;v_slug text;v_room_name text;v_room uuid;
begin
 select * into b from public.online_bookings where id=p_id and booking_private.has_booking_access(id,p_token);
 if not found then raise exception 'Booking not found.' using errcode='P0002';end if;
 perform booking_private.expire_room(b.room_id);select * into b from public.online_bookings where id=p_id;
 select * into r from public.reservations where id=b.reservation_id;
 select rr.room_id,rm.room_number,l.slug into v_room,v_room_name,v_slug from public.reservation_rooms rr
  join public.rooms rm on rm.id=rr.room_id left join public.online_room_listings l on l.room_id=rr.room_id
  where rr.reservation_id=b.reservation_id order by rr.id limit 1;
 if r.id is not null then
  select sum(n.charged_rate_kobo) into total from public.reservation_night_rates n where n.reservation_id=r.id and n.service_date>=r.arrival_date and n.service_date<r.departure_date;
  if total is null then raise exception 'The current agreed stay price is unavailable.' using errcode='23514';end if;
 else total:=b.quoted_total_kobo;end if;
 paid:=booking_private.received(b.reservation_id);
 return jsonb_build_object('id',b.id,'reference',b.payment_reference,'slug',coalesce(v_slug,b.slug),'roomName',v_room_name,
  'state',b.state,'reservationStatus',r.status,'arrival',coalesce(r.arrival_date,b.arrival_date),'departure',coalesce(r.departure_date,b.departure_date),
  'guests',coalesce(r.adults,b.adults),'actualDeparture',r.actual_departure_date,'totalKobo',total,'paidKobo',paid,'dueNowKobo',b.due_now_kobo,
  'balanceKobo',case when b.state in ('confirmed','payment_pending','requested') then greatest(total-paid,0) else 0 end,
  'paymentPlan',b.payment_plan,'expiresAt',b.expires_at,'note',b.decision_note,'policy',b.accepted_policy,
  'checkoutUrl',case when b.state='payment_pending' then b.checkout_url end);
end $$;
notify pgrst,'reload schema';

-- Source: booking-reconciliation.sql
-- Provider observations are separate from cash receipts and approved ledger refunds.
create table if not exists public.booking_payment_checks(
 booking_id uuid primary key references public.online_bookings,organization_id uuid not null references public.organizations,
 property_id uuid not null references public.properties,checked_at timestamptz not null default now(),
 outcome text not null check(outcome in ('paid','unpaid','error')),last_error text
);
create table if not exists public.booking_provider_refunds(
 provider_id text primary key,booking_id uuid not null references public.online_bookings,organization_id uuid not null references public.organizations,
 property_id uuid not null references public.properties,amount_kobo bigint not null check(amount_kobo>0),
 provider_status text not null,checked_at timestamptz not null default now()
);
alter table public.booking_payment_checks enable row level security;
alter table public.booking_provider_refunds enable row level security;
revoke all on public.booking_payment_checks,public.booking_provider_refunds from public,anon,authenticated;
grant select on public.booking_payment_checks,public.booking_provider_refunds to authenticated,service_role;
drop policy if exists booking_payment_checks_staff_read on public.booking_payment_checks;
create policy booking_payment_checks_staff_read on public.booking_payment_checks for select to authenticated
 using(public.can_access_property(organization_id,property_id) and public.has_org_role(organization_id,array['owner','manager','front_desk','accountant']::public.member_role[]));
drop policy if exists booking_provider_refunds_staff_read on public.booking_provider_refunds;
create policy booking_provider_refunds_staff_read on public.booking_provider_refunds for select to authenticated
 using(public.can_access_property(organization_id,property_id) and public.has_org_role(organization_id,array['owner','manager','front_desk','accountant']::public.member_role[]));
create or replace function public.record_booking_payment_check(p_reference text,p_outcome text,p_error text) returns void
language plpgsql security definer set search_path='' as $$
declare b public.online_bookings%rowtype;
begin
 select * into b from public.online_bookings where payment_reference=p_reference;
 if not found then raise exception 'Booking not found.' using errcode='P0002';end if;
 if p_outcome is null or p_outcome not in ('paid','unpaid','error') or (p_outcome='paid' and b.payment_id is null) then raise exception 'Invalid payment check.' using errcode='22023';end if;
 insert into public.booking_payment_checks(booking_id,organization_id,property_id,outcome,last_error) values(b.id,b.organization_id,b.property_id,case when p_outcome='unpaid' and b.payment_id is not null then 'paid' else p_outcome end,left(p_error,200))
 on conflict(booking_id) do update set outcome=excluded.outcome,last_error=excluded.last_error,checked_at=now();
end $$;
create or replace function public.record_booking_provider_refund(p_provider_id text,p_reference text,p_amount bigint,p_currency text,p_status text) returns void
language plpgsql security definer set search_path='' as $$
declare b public.online_bookings%rowtype;v_old public.booking_provider_refunds%rowtype;
begin
 select * into b from public.online_bookings where payment_reference=p_reference;
 if not found then return;end if;
 if p_provider_id is null or p_provider_id !~ '^[0-9]{1,25}$' or p_amount is null or p_amount<=0 or p_amount>b.due_now_kobo or p_currency<>'NGN' or p_currency is null
  or p_status is null or p_status not in ('pending','processing','processed','failed','needs-attention') then raise exception 'Invalid provider refund observation.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-refund:'||p_provider_id,0));
 select * into v_old from public.booking_provider_refunds where provider_id=p_provider_id;
 if found and (v_old.booking_id<>b.id or v_old.amount_kobo<>p_amount) then raise exception 'Provider refund identity changed.' using errcode='23514';end if;
 insert into public.booking_provider_refunds(provider_id,booking_id,organization_id,property_id,amount_kobo,provider_status)
 values(p_provider_id,b.id,b.organization_id,b.property_id,p_amount,p_status)
 on conflict(provider_id) do update set provider_status=excluded.provider_status,checked_at=now();
end $$;
revoke all on function public.record_booking_payment_check(text,text,text),public.record_booking_provider_refund(text,text,bigint,text,text) from public,anon,authenticated;
grant execute on function public.record_booking_payment_check(text,text,text),public.record_booking_provider_refund(text,text,bigint,text,text) to service_role;
create or replace function public.claim_booking_payment_checks(p_limit integer) returns table(booking_id uuid,payment_reference text)
language plpgsql security definer set search_path='' as $$
begin
 return query with candidates as (
  select b.id,b.payment_reference,b.organization_id,b.property_id from public.online_bookings b
  left join public.booking_payment_checks c on c.booking_id=b.id
  where b.payment_plan<>'arrival' and b.payment_id is null and b.state in ('payment_pending','expired','cancelled')
   and b.checkout_url is not null and b.created_at>now()-interval '7 days' and (c.checked_at is null or c.checked_at<now()-interval '10 minutes')
  order by coalesce(c.checked_at,b.created_at) for update of b skip locked limit least(greatest(p_limit,1),10)
 ), claimed as (
  insert into public.booking_payment_checks as checks(booking_id,organization_id,property_id,outcome,last_error)
  select id,organization_id,property_id,'error','Payment check started; awaiting provider response.' from candidates
  on conflict on constraint booking_payment_checks_pkey do update set checked_at=now(),outcome='error',last_error=excluded.last_error returning checks.booking_id
 ) select c.id,c.payment_reference from candidates c join claimed j on j.booking_id=c.id;
end $$;
revoke all on function public.claim_booking_payment_checks(integer) from public,anon,authenticated;
grant execute on function public.claim_booking_payment_checks(integer) to service_role;
create or replace function public.get_booking_refund_reconciliation(p_property_id uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare o uuid;v_result jsonb;
begin
 select organization_id into o from public.dojworld_settings where property_id=p_property_id;
 if o is null or not(public.can_access_property(o,p_property_id) and public.has_org_role(o,array['owner','manager','front_desk','accountant']::public.member_role[])) then raise exception 'Hotel access required.' using errcode='42501';end if;
 select coalesce(jsonb_agg(row_data order by latest desc),'[]'::jsonb) into v_result from (
  select max(p.checked_at) latest,jsonb_build_object('bookingId',b.id,'reference',b.payment_reference,'reservationId',b.reservation_id,
   'processedKobo',coalesce(sum(p.amount_kobo) filter(where p.provider_status='processed'),0),
   'recordedKobo',(select coalesce(sum(r.amount_kobo),0) from public.payment_refunds r where r.payment_id=b.payment_id),
   'refunds',jsonb_agg(jsonb_build_object('id',p.provider_id,'amountKobo',p.amount_kobo,'status',p.provider_status,'checkedAt',p.checked_at) order by p.provider_id)) row_data
  from public.online_bookings b join public.booking_provider_refunds p on p.booking_id=b.id
  where b.organization_id=o and b.property_id=p_property_id group by b.id
 ) rows;
 return v_result;
end $$;
revoke all on function public.get_booking_refund_reconciliation(uuid) from public,anon;
grant execute on function public.get_booking_refund_reconciliation(uuid) to authenticated;
notify pgrst,'reload schema';

notify pgrst,'reload schema';
commit;
